-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.anki_cards (
  note_guid text not null,
  ord smallint not null,
  deck_id text not null,
  front_html text not null,
  back_html text not null,
  sort_field text default ''::text not null,
  constraint anki_cards_pkey PRIMARY KEY (note_guid, ord),
  constraint anki_cards_deck_id_fkey FOREIGN KEY (deck_id) REFERENCES public.anki_decks(id),
  constraint anki_cards_note_guid_fkey FOREIGN KEY (note_guid) REFERENCES public.anki_notes(guid) ON DELETE CASCADE,
  constraint anki_cards_ord_check CHECK ((ord >= 0))
);

CREATE INDEX anki_cards_deck ON public.anki_cards USING btree (deck_id);

CREATE TRIGGER anki_card_added AFTER INSERT ON public.anki_cards FOR EACH ROW EXECUTE FUNCTION public.anki_card_changed();
CREATE TRIGGER anki_card_moved AFTER UPDATE OF deck_id ON public.anki_cards FOR EACH ROW WHEN ((old.deck_id IS DISTINCT FROM new.deck_id)) EXECUTE FUNCTION public.anki_card_changed();
CREATE TRIGGER anki_card_removed AFTER DELETE ON public.anki_cards FOR EACH ROW EXECUTE FUNCTION public.anki_card_changed();

alter table public.anki_cards enable row level security;

grant delete, insert, maintain, references, select, trigger, truncate, update on table public.anki_cards to service_role;
